@sig trait ImageResultAssessment_Api {
  def id: Art.BridgeId
  def image_feedback_Id : Art.PortId
  def image_result_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var image_result_facts: EIT_Acquisition_Supervisor.ImageResultFacts.Type = $

  def put_image_result_facts(value : EIT_Acquisition_Supervisor.ImageResultFacts.Type) : Unit = {
    Contract(
      Modifies(image_result_facts),
      Ensures(
        image_result_facts == value
      )
    )
    Spec {
      image_result_facts = value
    }

    Art.putValue(image_result_facts_Id, EIT_Acquisition_Supervisor.ImageResultFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ImageResultAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val image_feedback_Id : Art.PortId,
  val image_result_facts_Id : Art.PortId) extends ImageResultAssessment_Api

@datatype class ImageResultAssessment_Operational_Api (
  val id: Art.BridgeId,
  val image_feedback_Id : Art.PortId,
  val image_result_facts_Id : Art.PortId) extends ImageResultAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var image_feedback: EIT_Acquisition_Supervisor.ImageFeedback.Type = $

  def get_image_feedback() : Option[EIT_Acquisition_Supervisor.ImageFeedback.Type] = {
    Contract(
      Ensures(
        Res == Some(image_feedback)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.ImageFeedback.Type] = Art.getValue(image_feedback_Id) match {
      case Some(EIT_Acquisition_Supervisor.ImageFeedback_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port image_feedback.  Expecting 'EIT_Acquisition_Supervisor.ImageFeedback_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.ImageFeedback.Type]()
      case _ => None[EIT_Acquisition_Supervisor.ImageFeedback.Type]()
    }
    return value
  }
}
